ev("dr25e","2025-12-15","드리미",AS,"드리미가 A/S 서비스 니어바이를 롯데하이마트, SK네트웍스서비스와 3사 협의로 넓혀 전국 롯데하이마트 지점에서 구매처와 상관없이 수리를 접수한다(음식물처리기 제외).",["dr_bw2512"],tags=["하이마트"],imp=3,flags=["접수 거점 수는 기사에 없음"])
