ev("xm25a","2025-01-15","샤오미코리아",CH,"샤오미코리아의 공식 판매 채널은 샤오미코리아 홈페이지, 쿠팡, 네이버이며 이동통신 3사 유통망으로도 판매한다.",["xm_mt2501","xm_nc2501"],imp=3)
ev("xm25b","2025-06-18","샤오미코리아",CH,"샤오미는 첫 국내 공식 매장을 6월 28일 IFC몰 여의도점 L2층에 연다고 알렸다. 약 60평이며 판매와 AS를 한곳에서 한다. 청소기 2년, TV 3년 무상 보증과 무료 방문 수거·수리를 내걸었다. 배송은 도심 48시간, 도서산간 72시간, 86·100형 TV 설치는 2~3일이다.",["xm_ins2506","xm_st2506"],tags=["직영형 스토어"],imp=3)
ev("xm25c","2025-06-28","샤오미코리아",CH,"샤오미 스토어 IFC몰 여의도점이 6월 28일 문을 열었다. 부동산 자문은 CBRE코리아가 맡았다. 온라인과 오프라인의 가격·모델은 같다.",["xm_dd2506","xm_stt2506","xm_sd2506"],tags=["직영형 스토어"],imp=3,flags=["개점일은 예고 기사 기준이며 개점 후 기사로 직접 확인하지 못함"])
ev("xm25d","2025-09-27","샤오미코리아",CH,"샤오미가 9월 27일 2호점 구의 NC이스트폴점, 3호점 마곡 원그로브점을 열었다. 1호점 개점일 방문객은 7,400명, 7월 일평균은 약 3,000명이라고 밝혔다. 1호점 판매 비중은 스마트폰 플래그십 40%, 패드7 31%, TV S 미니 60%다.",["xm_sd2509","xm_ins2509"],claim="자사 집계",tags=["직영형 스토어"],imp=3,flags=["판매 비중의 모수는 기사에 없음","방문객 수는 샤오미 발표이며 독립 검증 못 함"])
ev("xm25e","2025-09-25","샤오미코리아",CO,"샤오미가 이랜드·현대백화점과 리테일, SSG닷컴·네이버와 이커머스, 은행과 무이자 할부, 티머니와 모바일 결제 협력을 밝혔다. 온라인 무료 배송은 1만 5천 원 이상 구매 기준이다.",["xm_sd2509","xm_ins2509"],flags=["협력 사항이 예정인지 시행 중인지 구분이 기사에 없음"])
ev("xm25f","2025-11","샤오미코리아",CH,"코리아중앙데일리는 샤오미가 광진·강서에 매장을 열었고 부천과 잠실에 4·5호점을 곧 열 계획이라고 전했다.",["xm_jd"],imp=3,flags=["광진·강서 개점일은 기사에 없음","9월 27일 구의·마곡과 기사의 광진·강서 표기가 같은 매장인지 확인 필요"])
